INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N032-01','CN0268','S031-01','历史园区水量','第5行','2022/23/24为278/352/316m³/d，环评89，规模取352；列已建，行业栏为化学试剂和助剂制造。此园区统计无特征污染物备注不等于没有污染物。','WEB_PRIMARY','公开正文/摘录','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N032-02','CN0268','S032-01','技改分质及膜界限','4.3.2、表4.3-7至11','晶化、酸化洗涤分段回用；物料膜过滤、制纯水RO为生产/公用设备，不能算末端废水膜；晶化母液蒸馏后51.4t/a进入污水收集，结论另称母液和首洗液焚烧，具体连接存在表述差异，保留。设计生产水汇总28730.7t/a，制纯水浓水冷却补水11800m³/a（正文亦以t/a表示排水），不重复求和。酸洗源强氨氮8.82、总氮6.23mg/L，原表内部不一致。','WEB_PRIMARY','公开正文/摘录','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N032-03','CN0268','S032-01','残余物及纳管','表4.3-15、4.3.2','高浓废液663.6t/a设计自身焚烧；污水污泥0.3t/a；废渗透膜0.2t/a属制纯水，均非现行实绩；园区纳管后水阁污水厂，现行管网待核。','WEB_PRIMARY','公开正文/摘录','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N032-04','CN0269','S032-03','许可范围','公告18号','许可编号6502040128，HW46 900-037-46及HW50 251-016-50、251-018-50、251-019-50、261-152-50、261-156-50合计3000t/a，2023-04-26至2028-04-25。','WEB_PRIMARY','公开正文/摘录','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N032-05','CN0269','S032-04','建成及运行披露','防治污染设施建设和运行、废水段','转载企业披露称2023年5月建成，此后正常运行，碱液循环；不证明现时满负荷或预处理具体单元。','WEB_SECONDARY','公开正文/摘录','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N032-06','CN0270','S032-06','转移许可','粤环穗审〔2025〕45号','420吨废加氢精制剂及200吨废加氢裂化剂获批转移至该厂，许可至2025-12-31；非实际转移量。','WEB_PRIMARY','公开正文/摘录','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N032-07','CN0270','S032-07','许可规模复核','名单第34行','规划征求意见稿列HW46/HW50合计10000t/a，与2022名单一致；仍需核现行设施及实际生产。','WEB_PRIMARY','公开正文/摘录','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N032-08','CN0266','S032-08','水工艺出处交叉校核','12月16日第4项','与031的12月15日拟审批同项目，保留12月16日具体水、固废段可读出处，非新增项目或重复水量。','WEB_PRIMARY','公开正文/摘录','2026-11-27');
