INSERT INTO membrane_reviews (review_id,site_id,diagram_id,scope_key,stage,period,revision,presence,source_id,evidence_basis,gaps,updated_on) VALUES ('R032-01','CN0268','D032-01','td320_2018_design','design','2018-12报批稿',1,'not_identified','S032-01','仅2018技改设计；母液/首洗焚烧与蒸馏描述存在差异，未强行连接；生产物料过滤膜和公用RO不算末端工业水膜','2026现行图、分质实际水质、浓液去向、站能力、成本','2026-11-27');
INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('A032-01','R032-01','CN0268','td320_2018_design','screening',1,'分质减量及资源化','先验证母液分质与酸碱水中和；低盐洗涤水可筛UF/RO，高盐高COD母液需先验证有机回收/蒸馏，不能直接全流膜化','conditional','实际流量、离子与COD、膜试验、浓水合规出路及经济性均须核实','仅2018技改设计；母液/首洗焚烧与蒸馏描述存在差异，未强行连接；生产物料过滤膜和公用RO不算末端工业水膜','INFERRED，非现场已建事实','2026现行图、分质实际水质、浓液去向、站能力、成本','分股采样、物料衡算、膜污染及回收率小试、现有处理成本对比','优化分质回用及已有预处理',NULL,NULL,NULL,NULL,NULL,NULL,'现场数据不足，不赋风险分','2026-11-27');
