INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('A032-02','R032-02','CN0269','alkali_scrubbing_design','screening',1,'分质减量及资源化','先核循环碱液寿命与污染物组成；若可分离盐和残碱，验证分质回收及膜耐碱性，既有接管处理作为比较基线','conditional','实际流量、离子与COD、膜试验、浓水合规出路及经济性均须核实','批复规定设计去向，2025转载仅支持碱液循环，不能确认下游实际膜','INFERRED，非现场已建事实','排污量、盐种、碱液处置量、预处理单元、费用','分股采样、物料衡算、膜污染及回收率小试、现有处理成本对比','优化分质回用及已有预处理',NULL,NULL,NULL,NULL,NULL,NULL,'现场数据不足，不赋风险分','2026-11-27');
