CREATE VIEW v_membrane_evidence_boundaries AS SELECT r.*, CASE WHEN r.review_id IN ('MR014-005','MR016-006','MR011-05','MR013-007','MR014-001','MR014-002','MR014-009','MR014-004','MR011-15','MR016-008','MR016-009','MR010-10','MR014-003','MR017-009','MR011-18','MR010-09','MR021-008','MR013-002','MR011-14','MR010-07','MR018-008','MR020-002','MR022-002','R030-02','MR010-01','MR011-06','MR010-03','MR011-02','MR013-001','R024-03','R025-01','MR023-006','MR011-21','MR022-001','MR016-002') THEN 'industrial_direct' WHEN r.review_id IN ('MR017-005','R026-07','MR020-001','MR018-005','MR016-013','R026-06','MR015-003','R026-02') THEN 'industrial_shared' WHEN r.review_id IN ('R031-04') THEN 'domestic_only' WHEN r.review_id IN ('MR015-001') THEN 'reaction_not_separation' WHEN r.review_id IN ('R031-02') THEN 'process_water_unresolved' WHEN r.review_id IN ('MR019-001') THEN 'feed_unresolved' ELSE 'unclassified' END AS application_boundary FROM v_latest_membrane_reviews r WHERE presence='confirmed_present';
CREATE VIEW v_membrane_boundary_counts AS SELECT application_boundary,stage,COUNT(*) AS scope_count,COUNT(DISTINCT site_id) AS site_count FROM v_membrane_evidence_boundaries GROUP BY application_boundary,stage;
